wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment fetch, as requested by the graph's author. The result is
        // deliberately unused so the node's output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&published.date)
        );
        let _ = http_client::fetch(&url);

        let mut recorded: u32 = 0;
        if published.published {
            for id in &published.considered {
                state_rw::put(id, &published.date);
                recorded += 1;
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

I used the digest's `date` as the query text, since `PublishedDigest` has no text field. Ids are marked seen only when `published` is true, so an unpublished digest records 0 and its items can be retried. If you meant a different field for the query, or want ids recorded regardless of `published`, both are one-line changes.

